module donald_game #(\n    parameter MAX_ROUNDS = 8,\n    parameter COIN_WIDTH = 8,\n    parameter DISTR_WIDTH = 4,\n    parameter CLK_PERIOD = 10\n)(\n    // Inputs\n    input [COIN_WIDTH-1:0] d,\n    input [COIN_WIDTH-1:0] g,\n    input [DISTR_WIDTH-1:0] n,\n    input [DISTR_WIDTH-1:0] k,\n    input clk,\n    input rst_n,\n    input start,\n    \n    // Outputs\n    output reg [COIN_WIDTH-1:0] M,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH = 2'd2;\n    \n    reg [1:0] state;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    \n    // DP table storage\n    reg [COIN_WIDTH-1:0] dp_table [0:MAX_ROUNDS][0:255][0:MAX_ROUNDS];\n    \n    // Computation registers\n    reg [COIN_WIDTH-1:0] total_coins;\n    reg [COIN_WIDTH-1:0] best_value;\n    reg [COIN_WIDTH-1:0] current_bet;\n    reg [COIN_WIDTH-1:0] val_win;\n    reg [COIN_WIDTH-1:0] val_lose;\n    reg [COIN_WIDTH-1:0] min_val;\n    \n    // Index registers\n    reg [3:0] round_idx;\n    reg [7:0] d_coins_idx;\n    reg [3:0] distr_idx;\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            M <= 8'd0;\n            cycle_count <= 8'd0;\n            round_idx <= 4'd0;\n            d_coins_idx <= 8'd0;\n            distr_idx <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        total_coins <= d + g;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    \n                    // Initialize DP table base cases\n                    if (round_idx == MAX_ROUNDS) begin\n                        dp_table[MAX_ROUNDS][d_coins_idx][distr_idx] <= d_coins_idx;\n                        \n                        // Increment indices\n                        if (d_coins_idx == 8'd255 && distr_idx == 4'd8) begin\n                            round_idx <= round_idx - 4'd1;\n                            d_coins_idx <= 8'd0;\n                            distr_idx <= 4'd0;\n                        end else if (distr_idx == 4'd8) begin\n                            d_coins_idx <= d_coins_idx + 8'd1;\n                            distr_idx <= 4'd0;\n                        end else begin\n                            distr_idx <= distr_idx + 4'd1;\n                        end\n                    end else begin\n                        // Compute DP values for current state\n                        best_value <= 8'd0;\n                        \n                        // Try all possible bets (simplified for synthesis)\n                        current_bet <= 8'd0;\n                        \n                        // Compute min of win/lose scenarios\n                        if (distr_idx > 4'd0) begin\n                            val_win <= dp_table[round_idx + 4'd1][d_coins_idx + current_bet][distr_idx - 4'd1];\n                        end else begin\n                            val_win <= 8'd0;\n                        end\n                        \n                        val_lose <= dp_table[round_idx + 4'd1][d_coins_idx - current_bet][distr_idx];\n                        \n                        if (val_win < val_lose) begin\n                            min_val <= val_win;\n                        end else begin\n                            min_val <= val_lose;\n                        end\n                        \n                        // Update best value\n                        if (min_val > best_value) begin\n                            best_value <= min_val;\n                        end\n                        \n                        // Store result\n                        dp_table[round_idx][d_coins_idx][distr_idx] <= best_value;\n                        \n                        // Increment indices\n                        if (d_coins_idx == 8'd255 && distr_idx == 4'd8) begin\n                            round_idx <= round_idx - 4'd1;\n                            d_coins_idx <= 8'd0;\n                            distr_idx <= 4'd0;\n                        end else if (distr_idx == 4'd8) begin\n                            d_coins_idx <= d_coins_idx + 8'd1;\n                            distr_idx <= 4'd0;\n                        end else begin\n                            distr_idx <= distr_idx + 4'd1;\n                        end\n                    end\n                    \n                    // Check completion\n                    if (round_idx == 4'd0 && d_coins_idx == 8'd0 && distr_idx == 4'd0 && cycle_count >= MAX_CYCLES) begin\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    M <= dp_table[0][d][k];\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule